    /** What happened in one turn, by player id (for the referee summary and the viewer). */
    static final class TurnReport {
        public final Command[] commands;
        /** Reason the command became WAIT, or null. */
        public final String[] invalid;
        public final int[] gain;
        /** Null for inactive players. */
        public final Beam[] beams;
        public final List<Integer> placed = new ArrayList<>(), turned = new ArrayList<>(), activated = new ArrayList<>(), broken = new ArrayList<>();

        TurnReport(int players, Command[] commands) {
            this.commands = commands;
            invalid = new String[players];
            gain = new int[players];
            beams = new Beam[players];
        }
    }

    /** One game, DESIGN FINAL RULES F6; switches and constants in Config. */
    static final class Game {
        public final Config cfg;
        public final Board board;
        public final int playerCount;
        public final int[] seatOf, score, mirrorsLeft;
        public final boolean[] active;
        /** streak[player][cell], 0..streakCap. */
        public final int[][] streak;
        /** Per cell: player who lit the crystal alone last turn, -1 nobody, -2 contested. */
        public final int[] litBy;
        /** Mirrors that shattered at the end of the last turn: {cell, final type} (V5.8 echo, information only). */
        public final java.util.List<int[]> lastShattered = new java.util.ArrayList<>();
        /** Consecutive turns each player did nothing (WAIT or an impossible action). */
        public final int[] idleTurns;
        private String earlyReason;
        private boolean fastForwarding;
        /** Turns played; the current turn number is turn + 1. */
        public int turn;
        private int suppliedTurn;

        public Game(Board board, int playerCount, Config cfg) {
            this(board, Seats.seatsFor(playerCount), cfg);
        }

        /** @param seatOf seat of each player id (bots use relative ids: themselves first, then clockwise). */
        public Game(Board board, int[] seatOf, Config cfg) {
            this.cfg = cfg;
            this.board = board;
            this.playerCount = seatOf.length;
            this.seatOf = seatOf.clone();
            score = new int[playerCount];
            mirrorsLeft = new int[playerCount];
            active = new boolean[playerCount];
            streak = new int[playerCount][board.n * board.n];
            idleTurns = new int[playerCount];
            litBy = new int[board.n * board.n];
            Arrays.fill(litBy, -1);
            for (int id = 0; id < playerCount; id++) {
                mirrorsLeft[id] = cfg.mirrorStock;
                active[id] = true;
            }
            for (int p = 0; p < board.n * board.n; p++)
                if (board.mirrorType[p] >= 0 && board.pending[p] == 0) board.mirrorLife[p] = cfg.mirrorLife;
            // F6.2 / QA Q5: the lamp cell of a seat without a player is an ordinary Empty cell
            boolean[] held = new boolean[4];
            for (int s : seatOf) held[s] = true;
            for (int s = 0; s < 4; s++)
                if (!held[s]) {
                    int p = Seats.lampCell(s, board.n, board.e);
                    board.kind[p] = Board.EMPTY;
                    board.lampSeat[p] = -1;
                }
        }

        public static Game fromSeed(long seed, int playerCount, Config cfg) {
            return new Game(MapGenerator.generate(seed, cfg.walls, cfg.multiValues), playerCount, cfg);
        }

        /** Deep copy, optionally under other rules (bots simulate with buildDelay off). */
        public Game copyWith(Config rules) {
            Board b = board.copy();
            int[] life = b.mirrorLife.clone();
            Game g = new Game(b, seatOf, rules);
            System.arraycopy(life, 0, b.mirrorLife, 0, life.length);
            System.arraycopy(score, 0, g.score, 0, playerCount);
            System.arraycopy(mirrorsLeft, 0, g.mirrorsLeft, 0, playerCount);
            System.arraycopy(active, 0, g.active, 0, playerCount);
            for (int id = 0; id < playerCount; id++) System.arraycopy(streak[id], 0, g.streak[id], 0, streak[id].length);
            System.arraycopy(litBy, 0, g.litBy, 0, litBy.length);
            g.turn = turn;
            g.suppliedTurn = suppliedTurn;
            return g;
        }

        public Game copy() {
            return copyWith(cfg);
        }

        public int currentTurn() {
            return turn + 1;
        }

        public boolean awake(int p, int turnNumber) {
            return !cfg.tides || (turnNumber + board.phase[p]) % cfg.tideCycle < cfg.tideAwake;
        }

        /** Per seat: Board.SEAT_ACTIVE, SEAT_INACTIVE or SEAT_EMPTY. */
        public int[] seatStates() {
            int[] s = {Board.SEAT_EMPTY, Board.SEAT_EMPTY, Board.SEAT_EMPTY, Board.SEAT_EMPTY};
            for (int id = 0; id < playerCount; id++) s[seatOf[id]] = active[id] ? Board.SEAT_ACTIVE : Board.SEAT_INACTIVE;
            return s;
        }

        /** F8: lamp becomes a wall, hand discarded, its mirrors stay, zone stays protected, score -1. */
        public void deactivate(int id) {
            active[id] = false;
            mirrorsLeft[id] = 0;
            score[id] = -1;
        }

        public int activeCount() {
            int c = 0;
            for (boolean a : active) if (a) c++;
            return c;
        }

        public boolean isOver() {
            return earlyReason != null || turn >= cfg.maxTurns || activeCount() < 2;
        }

        /** Why the game ended: "decided", "stale", "fewer than two players", "max turns"; null while it runs. */
        public String endReason() {
            if (earlyReason != null) return earlyReason;
            if (activeCount() < 2) return "fewer than two players";
            return turn >= cfg.maxTurns ? "max turns" : null;
        }

        /** B of V5.5: most points one player can score in a turn (streak cap x sum of values, + strike). */
        public int maxGainPerTurn() {
            int sum = 0;
            for (int p = 0; p < board.n * board.n; p++) if (board.kind[p] == Board.CRYSTAL) sum += board.value[p];
            return (cfg.contested ? cfg.streakCap : 1) * sum + cfg.strikeBonus;
        }

        /** V5.5 decided: every pair of active players is further apart than turns left x B. */
        boolean decided() {
            long bound = (long) (cfg.maxTurns - turn) * maxGainPerTurn();
            for (int i = 0; i < playerCount; i++)
                for (int j = i + 1; j < playerCount; j++)
                    if (active[i] && active[j] && Math.abs(score[i] - score[j]) <= bound) return false;
            return true;
        }

        boolean stale() {
            for (int id = 0; id < playerCount; id++) if (active[id] && idleTurns[id] < cfg.staleTurns) return false;
            return true;
        }

        /** End of turn (F6 step 8 + V5.5): decided, or stale = the referee plays the remaining turns with everyone waiting. */
        private void earlyEndCheck() {
            if (!cfg.earlyEnd || fastForwarding || turn >= cfg.maxTurns || activeCount() < 2) return;
            if (decided()) earlyReason = "decided";
            else if (stale()) {
                fastForwarding = true;
                while (turn < cfg.maxTurns && activeCount() >= 2) playTurn(new Command[playerCount]);
                fastForwarding = false;
                earlyReason = "stale";
            }
        }

        /** F6 step 0, before the input of the current turn is sent; idempotent within a turn. */
        public void beginTurn() {
            int t = currentTurn();
            if (suppliedTurn == t) return;
            suppliedTurn = t;
            if (cfg.supplyEvery > 0 && t % cfg.supplyEvery == 0)
                for (int id = 0; id < playerCount; id++)
                    if (active[id]) mirrorsLeft[id] = Math.min(cfg.handMax, mirrorsLeft[id] + 1);
        }

        /** @param cmds by player id; null entries (or inactive players) count as WAIT. */
        public TurnReport playTurn(Command[] cmds) {
            beginTurn();
            TurnReport r = new TurnReport(playerCount, cmds);
            lastShattered.clear();
            int[] placeAt = new int[playerCount], turnAt = new int[playerCount];
            for (int id = 0; id < playerCount; id++) {
                placeAt[id] = -1;
                turnAt[id] = -1;
                if (!active[id] || cmds[id] == null) continue;
                String why = validate(id, cmds[id]);
                if (why != null) r.invalid[id] = why;
                else if (cmds[id].kind == Command.Kind.PLACE) placeAt[id] = Geometry.idx(cmds[id].x, cmds[id].y, board.n);
                else if (cmds[id].kind == Command.Kind.TURN) turnAt[id] = Geometry.idx(cmds[id].x, cmds[id].y, board.n);
            }
            boolean[] placed = new boolean[board.n * board.n], turned = new boolean[board.n * board.n];
            applyPlaces(cmds, placeAt, r, placed);
            applyTurns(turnAt, r, placed, turned);
            int[] states = seatStates();
            for (int id = 0; id < playerCount; id++) if (active[id]) r.beams[id] = BeamTracer.trace(board, seatOf[id], states);
            scoreCrystals(r);
            for (int id = 0; id < playerCount; id++)
                if (r.beams[id] != null && r.beams[id].stop == Beam.Stop.STRIKE) r.gain[id] += cfg.strikeBonus;
            for (int id = 0; id < playerCount; id++) if (active[id]) score[id] += r.gain[id];
            advanceMirrors(r, placed, turned);
            for (int id = 0; id < playerCount; id++) {
                boolean acted = placeAt[id] >= 0 && r.invalid[id] == null || turnAt[id] >= 0;
                idleTurns[id] = acted ? 0 : idleTurns[id] + 1;
            }
            turn++;
            earlyEndCheck();
            return r;
        }

        /** Null when valid, else the reason (the command becomes WAIT). */
        public String validate(int id, Command c) {
            if (c.kind == Command.Kind.WAIT) return null;
            int n = board.n;
            if (!Geometry.inside(c.x, c.y, n)) return "cell out of the board";
            int p = Geometry.idx(c.x, c.y, n);
            int zone = Seats.zoneSeat(c.x, c.y, n, board.e);
            int zoneOwner = zone >= 0 && zone != seatOf[id] ? playerAtSeat(zone) : -1;
            if (c.kind == Command.Kind.PLACE) {
                if (c.type != 0 && c.type != 1) return "type must be 0 or 1";
                if (board.kind[p] != Board.EMPTY || board.mirrorType[p] >= 0) return "cell not empty";
                if (zoneOwner >= 0) return "cell in zone of player " + zoneOwner;
                if (mirrorsLeft[id] <= 0) return "no mirror in hand";
                return null;
            }
            if (!cfg.turnAllowed) return "TURN not available in this league";
            if (board.mirrorType[p] < 0) return "no mirror there";
            if (board.pending[p] > 0) return "mirror still pending";
            if (board.mirrorLock[p] > 0) return "mirror locked " + board.mirrorLock[p] + " more turns";
            if (zoneOwner >= 0) return "cell in zone of player " + zoneOwner;
            return null;
        }

        private int playerAtSeat(int seat) {
            for (int id = 0; id < playerCount; id++) if (seatOf[id] == seat) return id;
            return -1;
        }

        private void applyPlaces(Command[] cmds, int[] placeAt, TurnReport r, boolean[] placed) {
            Map<Integer, Integer> count = new HashMap<>();
            for (int p : placeAt) if (p >= 0) count.merge(p, 1, Integer::sum);
            for (int id = 0; id < playerCount; id++) {
                int p = placeAt[id];
                if (p < 0) continue;
                if (count.get(p) > 1) {
                    r.invalid[id] = "collision";
                    continue;
                }
                board.mirrorType[p] = cmds[id].type;
                board.lastToucher[p] = id;
                board.mirrorLife[p] = cfg.mirrorLife;
                mirrorsLeft[id]--;
                if (cfg.buildDelay) {
                    board.pending[p] = 1;
                    board.mirrorLock[p] = 0;
                } else board.mirrorLock[p] = cfg.lock;
                placed[p] = true;
                r.placed.add(p);
            }
        }

        private void applyTurns(int[] turnAt, TurnReport r, boolean[] placed, boolean[] turned) {
            for (int id = 0; id < playerCount; id++) {
                int p = turnAt[id];
                // a valid TURN targets a mirror present at the start of the turn, so never one placed this turn
                if (p < 0 || turned[p]) continue;
                board.mirrorType[p] = 1 - board.mirrorType[p];
                board.mirrorLock[p] = cfg.lock;
                board.lastToucher[p] = id;
                turned[p] = true;
                r.turned.add(p);
            }
        }

        /** F6 step 6. */
        private void scoreCrystals(TurnReport r) {
            int cells = board.n * board.n, t = currentTurn();
            int[] lighters = new int[cells], lastLighter = new int[cells];
            boolean[][] lit = new boolean[playerCount][];
            for (int id = 0; id < playerCount; id++) {
                if (r.beams[id] == null) continue;
                lit[id] = new boolean[cells];
                for (int p : r.beams[id].lit) {
                    lit[id][p] = true;
                    lighters[p]++;
                    lastLighter[p] = id;
                }
            }
            for (int p = 0; p < cells; p++) {
                if (board.kind[p] != Board.CRYSTAL) continue;
                litBy[p] = lighters[p] == 0 ? -1 : lighters[p] == 1 ? lastLighter[p] : -2;
                if (!cfg.contested) {
                    for (int id = 0; id < playerCount; id++) if (lit[id] != null && lit[id][p]) r.gain[id] += board.value[p];
                    continue;
                }
                if (!awake(p, t)) {
                    for (int id = 0; id < playerCount; id++) streak[id][p] = 0;
                    continue;
                }
                for (int id = 0; id < playerCount; id++) {
                    boolean inL = lit[id] != null && lit[id][p];
                    if (lighters[p] == 1 && inL) {
                        streak[id][p] = Math.min(streak[id][p] + 1, cfg.streakCap);
                        r.gain[id] += board.value[p] * streak[id][p];
                    } else if (!inL) streak[id][p] = Math.max(streak[id][p] - 1, 0);
                }
            }
        }

        /** F6 step 7: activation, lock countdown, wear. */
        private void advanceMirrors(TurnReport r, boolean[] placed, boolean[] turned) {
            for (int p = 0; p < board.n * board.n; p++) {
                if (board.mirrorType[p] < 0 || placed[p]) continue;
                if (board.pending[p] > 0) {
                    board.pending[p] = 0;
                    board.mirrorLock[p] = cfg.lock;
                    r.activated.add(p);
                    continue;
                }
                if (turned[p]) continue;
                board.mirrorLock[p] = Math.max(board.mirrorLock[p] - 1, 0);
                if (board.mirrorLife[p] > 0 && --board.mirrorLife[p] == 0) {
                    lastShattered.add(new int[] {p, board.mirrorType[p]});
                    board.removeMirror(p);
                    r.broken.add(p);
                }
            }
        }
    }

    /** Seeded map generation, DESIGN.md section 3.3; the order of Random calls is part of the spec. */
    static final class MapGenerator {
        private MapGenerator() {}

        /** @param plain Wood 2 map: no walls, no start mirrors, crystals worth 1 (same Random calls). */
        public static Board generate(long seed, boolean plain) {
            return generate(seed, !plain, !plain);
        }

        /** @param withWalls walls and start mirrors; @param multiValues crystal values 1-3, else all 1. */
        public static Board generate(long seed, boolean withWalls, boolean multiValues) {
            Random rnd = new Random(mix(seed));
            int n = 13 + 2 * rnd.nextInt(4);
            int c = (n - 1) / 2;
            int e = 2 + rnd.nextInt(c - 3);
            List<Integer> cand = candidates(n, e);
            Collections.shuffle(cand, rnd);
            int a = cand.size();
            int k = Math.min(a, a / 4 + rnd.nextInt(3));
            int walls = Math.min(a - k, a / 10 + rnd.nextInt(2));
            int mirrors = Math.min(a - k - walls, 2 + rnd.nextInt(3));

            Board b = Board.empty(n, e);
            for (int i = 0; i < k; i++) {
                int r = rnd.nextInt(100);
                int v = !multiValues ? 1 : r < 50 ? 1 : r < 85 ? 2 : 3;
                placeRotated(b, cand.get(i), Board.CRYSTAL, v, -1);
            }
            for (int i = k; i < k + walls; i++)
                if (withWalls) placeRotated(b, cand.get(i), Board.WALL, 0, -1);
            for (int i = k + walls; i < k + walls + mirrors; i++) {
                int type = rnd.nextInt(2);
                if (withWalls) placeRotated(b, cand.get(i), Board.EMPTY, 0, type);
            }
            for (int i = 0; i < k; i++) {
                int ph = rnd.nextInt(45);
                for (int r = 0, p = cand.get(i); r < 4; r++, p = Geometry.rot(p, n)) b.phase[p] = ph;
            }
            b.setCrystal(c, c, multiValues ? 3 : 1);
            b.phase[Geometry.idx(c, c, n)] = 0;
            return b;
        }

        /** SplitMix64 finalizer: spreads consecutive seeds (java.util.Random's first draws are near-linear in them). */
        public static long mix(long seed) {
            long z = seed + 0x9E3779B97F4A7C15L;
            z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
            z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
            return z ^ (z >>> 31);
        }

        /** Cells of the quarter x in [0, c-1], y in [0, c], sorted by (y, x), off the border, lamp lines and zones. */
        public static List<Integer> candidates(int n, int e) {
            int c = (n - 1) / 2;
            List<Integer> out = new ArrayList<>();
            for (int y = 0; y <= c; y++)
                for (int x = 0; x <= c - 1; x++)
                    if (isCandidate(x, y, n, e)) out.add(Geometry.idx(x, y, n));
            return out;
        }

        private static boolean isCandidate(int x, int y, int n, int e) {
            if (x == 0 || y == 0) return false; // the quarter never reaches x = n-1 or y = n-1
            if (Seats.zoneSeat(x, y, n, e) >= 0) return false;
            for (int s = 0; s < 4; s++) if (Seats.onLampLine(s, x, y, n, e)) return false;
            return true;
        }

        private static void placeRotated(Board b, int p, int kind, int value, int mirrorType) {
            for (int r = 0; r < 4; r++) {
                b.kind[p] = kind;
                b.value[p] = value;
                if (mirrorType >= 0) b.mirrorType[p] = r % 2 == 0 ? mirrorType : 1 - mirrorType;
                p = Geometry.rot(p, b.n);
            }
        }
    }

    /** A player bot fed with the exact protocol lines (DESIGN 5.1 and V2.3). */
    static interface Bot {
        void init(List<String> initLines);

        /** @return one output line. */
        String act(List<String> turnLines);
    }

    /**
     * Reference reader of the V5.1c inputs of one player (DESIGN V5.8): rebuilds what the protocol leaves out (turn,
     * player count, every player's score and streaks, crystal cells) from the reef, the mirror lists and the hands.
     * Ids are relative: 0 is the reading player, then clockwise. The beams of turn t come from inputs t and t+1:
     * first leagues every listed mirror of t+1; with build delay the active mirrors of t+1 that were not pending at t,
     * plus the shattered-mirror echoes (life 0).
     */
    static final class Tracker {
        public final Config cfg;
        public int n, e, playerCount, turn;
        /** Seat of each relative player. */
        public int[] seatOf;
        public Board board;
        public final List<Integer> crystalCells = new ArrayList<>();
        public int[] score, hands;
        public int[][] streak;
        public boolean[] active;
        /** Mirrors of the last input: cell -> {type, lock, life}; type -1 = hidden (a rival's pending mirror). */
        public Map<Integer, int[]> mirrors = new HashMap<>();
        /** Tide of each crystal in the last input (index in crystalCells). */
        public int[] tide;
        /** litBy (relative) of each crystal in the last input. */
        public int[] litBy;

        public Tracker(Config cfg) {
            this.cfg = cfg;
        }

        /** Seat of a lamp from its edge: x = 0 seat 0 (fires E), y = 0 seat 1 (S), x = n-1 seat 2 (W), y = n-1 seat 3 (N). */
        static int seatOfLamp(int x, int y, int n) {
            return x == 0 ? 0 : y == 0 ? 1 : x == n - 1 ? 2 : 3;
        }

        /** e from a lamp of a known seat (seat s lamp is R^s(0, e)). */
        static int offsetOf(int seat, int x, int y, int n) {
            return seat == 0 ? y : seat == 1 ? n - 1 - x : seat == 2 ? n - 1 - y : x;
        }

        public void init(List<String> lines) {
            String reef = lines.get(0).trim();
            n = Integer.parseInt(lines.get(1).trim());
            int[] seatByRel = {-1, -1, -1, -1};
            for (int p = 0; p < n * n; p++) {
                char ch = reef.charAt(p);
                if (ch >= 'A' && ch <= 'D') {
                    int x = Geometry.x(p, n), y = Geometry.y(p, n), seat = seatOfLamp(x, y, n);
                    seatByRel[ch - 'A'] = seat;
                    e = offsetOf(seat, x, y, n);
                }
            }
            playerCount = 0;
            while (playerCount < 4 && seatByRel[playerCount] >= 0) playerCount++;
            seatOf = java.util.Arrays.copyOf(seatByRel, playerCount);
            board = Board.empty(n, e);
            boolean[] held = new boolean[4];
            for (int s : seatOf) held[s] = true;
            for (int s = 0; s < 4; s++)
                if (!held[s]) {
                    int p = Seats.lampCell(s, n, e);
                    board.kind[p] = Board.EMPTY;
                    board.lampSeat[p] = -1;
                }
            for (int p = 0; p < n * n; p++) {
                char ch = reef.charAt(p);
                if (ch == '#') board.kind[p] = Board.WALL;
                else if (ch >= '1' && ch <= '3') {
                    board.kind[p] = Board.CRYSTAL;
                    board.value[p] = ch - '0';
                    crystalCells.add(p);
                }
            }
            score = new int[playerCount];
            hands = new int[playerCount];
            active = new boolean[playerCount];
            java.util.Arrays.fill(active, true);
            streak = new int[playerCount][n * n];
            tide = new int[crystalCells.size()];
            litBy = new int[crystalCells.size()];
        }

        public void turn(List<String> lines) {
            int i = 0;
            String[] head = lines.get(i++).trim().split(" ");
            int[] newHands = new int[playerCount];
            for (int k = 0; k < playerCount; k++) newHands[k] = Integer.parseInt(head[1 + k]);
            Map<Integer, int[]> m = new HashMap<>();
            int count = Integer.parseInt(lines.get(i++).trim());
            for (int k = 0; k < count; k++) {
                String[] t = lines.get(i++).trim().split(" ");
                m.put(Geometry.idx(Integer.parseInt(t[0]), Integer.parseInt(t[1]), n),
                    new int[] {Integer.parseInt(t[2]), Integer.parseInt(t[3]), Integer.parseInt(t[4])});
            }
            if (turn > 0) scorePreviousTurn(m, newHands);
            int crystals = Integer.parseInt(lines.get(i++).trim());
            for (int k = 0; k < crystals; k++) {
                String[] t = lines.get(i++).trim().split(" ");
                tide[k] = Integer.parseInt(t[0]);
                litBy[k] = Integer.parseInt(t[1]);
            }
            hands = newHands;
            mirrors = m;
            score[0] = Integer.parseInt(head[0]);
            turn++;
        }

        /** Beams of the previous turn from the previous and the new mirror lists, then F6 step 6 scoring and strikes. */
        private void scorePreviousTurn(Map<Integer, int[]> next, int[] newHands) {
            for (int p = 0; p < n * n; p++) {
                board.mirrorType[p] = -1;
                board.pending[p] = 0;
            }
            for (Map.Entry<Integer, int[]> en : next.entrySet()) {
                int p = en.getKey(), type = en.getValue()[0], lock = en.getValue()[1], life = en.getValue()[2];
                boolean reflected;
                if (!cfg.buildDelay) reflected = true;
                else {
                    int[] before = mirrors.get(p);
                    reflected = life == 0 || (lock >= 0 && before != null && before[1] >= 0);
                }
                if (reflected && type >= 0) board.mirrorType[p] = type;
            }
            int[] states = {Board.SEAT_EMPTY, Board.SEAT_EMPTY, Board.SEAT_EMPTY, Board.SEAT_EMPTY};
            boolean[] fired = new boolean[playerCount];
            for (int k = 0; k < playerCount; k++) {
                fired[k] = newHands[k] != -1;
                states[seatOf[k]] = fired[k] ? Board.SEAT_ACTIVE : Board.SEAT_INACTIVE;
            }
            int cells = n * n;
            boolean[][] lit = new boolean[playerCount][];
            int[] lighters = new int[cells], gain = new int[playerCount];
            for (int k = 0; k < playerCount; k++) {
                if (!fired[k]) continue;
                Beam b = BeamTracer.trace(board, seatOf[k], states);
                lit[k] = new boolean[cells];
                for (int p : b.lit) {
                    lit[k][p] = true;
                    lighters[p]++;
                }
                if (b.stop == Beam.Stop.STRIKE) gain[k] += cfg.strikeBonus;
            }
            for (int c = 0; c < crystalCells.size(); c++) {
                int p = crystalCells.get(c);
                if (!cfg.contested) {
                    for (int k = 0; k < playerCount; k++) if (lit[k] != null && lit[k][p]) gain[k] += board.value[p];
                    continue;
                }
                if (cfg.tides && tide[c] < 0) {
                    for (int k = 0; k < playerCount; k++) streak[k][p] = 0;
                    continue;
                }
                for (int k = 0; k < playerCount; k++) {
                    boolean inL = lit[k] != null && lit[k][p];
                    if (lighters[p] == 1 && inL) {
                        streak[k][p] = Math.min(streak[k][p] + 1, cfg.streakCap);
                        gain[k] += board.value[p] * streak[k][p];
                    } else if (!inL) streak[k][p] = Math.max(streak[k][p] - 1, 0);
                }
            }
            for (int k = 0; k < playerCount; k++) {
                if (fired[k]) score[k] += gain[k];
                else if (active[k]) score[k] = -1;
                active[k] = fired[k];
            }
        }
    }

    /** Rebuilds a Game from protocol lines, so bots only use what a real player reads. */
    static final class BotState {
        public final Config cfg;
        public Game game;
        public int myId, playerCount, turns;
        /** Pending rival mirror whose type the input hides (stored as type 0 in the board). */
        public boolean[] unknownType;
        /** Cells where this bot placed a mirror. */
        public final Set<Integer> myPlaced = new HashSet<>();

        public BotState(Config cfg) {
            this.cfg = cfg;
        }

        /** The V5.1c reader that rebuilds rivals' scores and streaks (DESIGN V5.8). */
        public Tracker tracker;

        public void parseInit(List<String> lines) {
            tracker = new Tracker(cfg);
            tracker.init(lines);
            playerCount = tracker.playerCount;
            myId = 0; // V5.1c: the reading player is always 0
            game = new Game(tracker.board.copy(), tracker.seatOf, cfg);
            unknownType = new boolean[tracker.n * tracker.n];
        }

        public void parseTurn(List<String> lines) {
            tracker.turn(lines);
            Board b = game.board;
            Arrays.fill(b.mirrorType, -1);
            Arrays.fill(b.mirrorLock, 0);
            Arrays.fill(b.pending, 0);
            Arrays.fill(b.mirrorLife, -1);
            Arrays.fill(unknownType, false);
            for (java.util.Map.Entry<Integer, int[]> en : tracker.mirrors.entrySet()) {
                int p = en.getKey(), type = en.getValue()[0], lock = en.getValue()[1], life = en.getValue()[2];
                if (life == 0) continue; // echo of a shattered mirror: its cell is empty
                unknownType[p] = type < 0;
                b.mirrorType[p] = Math.max(0, type);
                b.pending[p] = lock < 0 ? 1 : 0;
                b.mirrorLock[p] = Math.max(0, lock);
                b.mirrorLife[p] = life;
            }
            int t = tracker.turn;
            Arrays.fill(game.litBy, -1);
            for (int c = 0; c < tracker.crystalCells.size(); c++) {
                int p = tracker.crystalCells.get(c);
                game.litBy[p] = tracker.litBy[c];
                if (cfg.tides) b.phase[p] = phaseFromTide(tracker.tide[c], t);
            }
            for (int k = 0; k < playerCount; k++) {
                game.score[k] = tracker.score[k];
                game.active[k] = tracker.hands[k] != -1;
                game.mirrorsLeft[k] = Math.max(0, tracker.hands[k]);
                System.arraycopy(tracker.streak[k], 0, game.streak[k], 0, game.streak[k].length);
            }
            game.turn = t - 1;
            turns++;
        }

        /** Crystal phase from the signed tide of turn t (k > 0 awake k more turns, -k asleep k more turns). */
        int phaseFromTide(int tide, int t) {
            int m = tide > 0 ? cfg.tideAwake - tide : cfg.tideCycle + tide;
            return Math.floorMod(m - t, cfg.tideCycle);
        }

        /** Copy for a 1-turn simulation: own pending mirrors act now, rival pending ones stay Empty, own new mirror acts now. */
        public Game simulation() {
            Config rules = cfg.copy();
            rules.buildDelay = false;
            Game g = game.copyWith(rules);
            for (int p : myPlaced) if (g.board.mirrorType[p] >= 0 && !unknownType[p]) g.board.pending[p] = 0;
            return g;
        }
    }

    /**
     * DESIGN 7 / V2.5 / V2.6 greedy bots. Candidates: WAIT, legal PLACE (both types) on own beam path cells, then legal
     * TURN of mirrors on that path. One-turn simulation with the others on WAIT; first best kept (WAIT unless strictly better).
     * SELF = Greedy-self (own lit values, no contest); FULL = G (own gain - 0.5 max rival gain); PLUS = G+ (G + next streak
     * value of crystals it keeps, skipping crystals dormant when its mirror activates). DESIGN F9.
     */
    static final class GreedyBot implements Bot {
        public enum Mode { SELF, FULL, PLUS }

        private final BotState s;
        private final Mode mode;

        public GreedyBot(Config cfg, Mode mode) {
            s = new BotState(cfg);
            this.mode = mode;
        }

        @Override
        public void init(List<String> initLines) {
            s.parseInit(initLines);
        }

        @Override
        public String act(List<String> turnLines) {
            s.parseTurn(turnLines);
            Command best = Command.waitCommand();
            double bestValue = evaluate(best);
            for (Command c : candidates()) {
                double v = evaluate(c);
                if (v > bestValue) {
                    bestValue = v;
                    best = c;
                }
            }
            if (best.kind == Command.Kind.PLACE) s.myPlaced.add(Geometry.idx(best.x, best.y, s.game.board.n));
            return best.text();
        }

        List<Command> candidates() {
            Game g = s.simulation();
            int me = s.myId, n = g.board.n;
            Beam path = BeamTracer.trace(g.board, g.seatOf[me], g.seatStates());
            List<Command> places = new ArrayList<>(), turns = new ArrayList<>();
            for (int p : path.cells) {
                int x = Geometry.x(p, n), y = Geometry.y(p, n);
                for (int t = 0; t < 2; t++) {
                    Command c = Command.place(x, y, t);
                    if (s.game.validate(me, c) == null) places.add(c);
                }
                Command c = Command.turn(x, y);
                if (s.game.board.mirrorType[p] >= 0 && s.game.validate(me, c) == null) turns.add(c);
            }
            places.addAll(turns);
            return places;
        }

        double evaluate(Command mine) {
            Game g = s.simulation();
            int me = s.myId;
            Command[] cmds = new Command[g.playerCount];
            for (int id = 0; id < g.playerCount; id++) cmds[id] = id == me ? mine : Command.waitCommand();
            TurnReport r = g.playTurn(cmds);
            if (mode == Mode.SELF) {
                int v = 0;
                for (int p : r.beams[me].lit) v += g.board.value[p];
                return v;
            }
            int rival = 0;
            for (int id = 0; id < g.playerCount; id++) if (id != me && g.active[id]) rival = Math.max(rival, r.gain[id]);
            double v = r.gain[me] - 0.5 * rival;
            if (mode == Mode.PLUS) {
                int activation = s.game.currentTurn() + (s.cfg.buildDelay && mine.kind == Command.Kind.PLACE ? 2 : 0);
                for (int p = 0; p < g.board.n * g.board.n; p++)
                    if (g.litBy[p] == me && s.game.awake(p, activation))
                        v += g.board.value[p] * Math.min(g.streak[me][p] + 1, g.cfg.streakCap);
            }
            return v;
        }
    }

    /**
     * Ladder bosses with a 2-turn own search (M5). Ply 1: all candidates of GreedyBot (own beam path) valued like G / G+;
     * the best WIDTH go to ply 2: the state after the command (rivals WAIT), candidates from the new own beam path,
     * value = v1 + best v2 (WAIT = 0 gain delta valued the same way). Rivals always WAIT. FULL = G2, PLUS = G+2.
     */
    static final class Boss2 implements Bot {
        private double rivalWeight = 0.5;
        private boolean allLanes;
        public Boss2 allLanes(boolean a) {
            allLanes = a;
            return this;
        }

        private final BotState s;
        private final GreedyBot.Mode mode;
        private final int width;
        private final double discount;
        /** > 0: Tide-rider term, value x awake turns among t+2..t+6 of every crystal lit alone after the move. */
        private double tideW;
        public Boss2 rivalWeight(double w) {
            rivalWeight = w;
            return this;
        }

        public Boss2 tide(double w) {
            tideW = w;
            return this;
        }

        public Boss2(Config cfg, GreedyBot.Mode mode, int width, double discount) {
            s = new BotState(cfg);
            this.mode = mode;
            this.width = width;
            this.discount = discount;
        }

        @Override
        public void init(List<String> l) {
            s.parseInit(l);
        }

        @Override
        public String act(List<String> turnLines) {
            s.parseTurn(turnLines);
            Game g0 = s.simulation();
            List<Command> cands = new ArrayList<>();
            cands.add(Command.waitCommand());
            cands.addAll(candidates(g0, s.game));
            int k = cands.size();
            double[] v1 = new double[k];
            Game[] after = new Game[k];
            for (int i = 0; i < k; i++) {
                after[i] = g0.copy();
                v1[i] = step(after[i], cands.get(i));
            }
            Integer[] order = new Integer[k];
            for (int i = 0; i < k; i++) order[i] = i;
            java.util.Arrays.sort(order, (a, b) -> Double.compare(v1[b], v1[a]));
            int best = 0;
            double bestV = Double.NEGATIVE_INFINITY;
            for (int r = 0; r < Math.min(width, k); r++) {
                int i = order[r];
                double v2 = 0;
                if (!after[i].isOver()) {
                    for (Command c2 : candidates(after[i], after[i])) {
                        Game t = after[i].copy();
                        v2 = Math.max(v2, step(t, c2));
                    }
                }
                double v = v1[i] + discount * v2;
                if (v > bestV + 1e-9 || (Math.abs(v - bestV) <= 1e-9 && i < best)) {
                    bestV = v;
                    best = i;
                }
            }
            Command c = cands.get(best);
            if (c.kind == Command.Kind.PLACE) s.myPlaced.add(Geometry.idx(c.x, c.y, s.game.board.n));
            return c.text();
        }

        private List<Command> candidates(Game g, Game validator) {
            int me = s.myId, n = g.board.n;
            java.util.Set<Integer> cells = new java.util.LinkedHashSet<>();
            for (int id = 0; id < g.playerCount; id++)
                if (g.active[id] && (allLanes || id == me)) cells.addAll(BeamTracer.trace(g.board, g.seatOf[id], g.seatStates()).cells);
            List<Command> places = new ArrayList<>(), turns = new ArrayList<>();
            for (int p : cells) {
                int x = Geometry.x(p, n), y = Geometry.y(p, n);
                for (int t = 0; t < 2; t++) {
                    Command c = Command.place(x, y, t);
                    if (validator.validate(me, c) == null) places.add(c);
                }
                Command c = Command.turn(x, y);
                if (g.board.mirrorType[p] >= 0 && validator.validate(me, c) == null) turns.add(c);
            }
            places.addAll(turns);
            return places;
        }

        /** Plays mine (rivals WAIT) on g and returns the G / G+ value of that turn. */
        private double step(Game g, Command mine) {
            int me = s.myId;
            int turnNo = g.currentTurn();
            Command[] cmds = new Command[g.playerCount];
            for (int id = 0; id < g.playerCount; id++) cmds[id] = id == me ? mine : Command.waitCommand();
            TurnReport r = g.playTurn(cmds);
            int rival = 0;
            for (int id = 0; id < g.playerCount; id++) if (id != me && g.active[id]) rival = Math.max(rival, r.gain[id]);
            double v = r.gain[me] - rivalWeight * rival;
            if (mode == GreedyBot.Mode.PLUS) {
                int activation = turnNo + (s.cfg.buildDelay && mine.kind == Command.Kind.PLACE ? 2 : 0);
                for (int p = 0; p < g.board.n * g.board.n; p++)
                    if (g.litBy[p] == me && g.awake(p, activation))
                        v += g.board.value[p] * Math.min(g.streak[me][p] + 1, g.cfg.streakCap);
            }
            if (tideW > 0)
                for (int p = 0; p < g.board.n * g.board.n; p++)
                    if (g.litBy[p] == me) {
                        int awake = 0;
                        for (int k = 2; k <= 6; k++) if (g.awake(p, turnNo + k)) awake++;
                        v += tideW * g.board.value[p] * awake / 5.0;
                    }
            return v;
        }
    }

    /**
     * M5 planner P. Candidates: WAIT, legal PLACE (both types) and TURN on cells of ANY active beam path (so it can cut or
     * deflect rivals). Each candidate is rolled out for H turns with the real rules (build delay, wear, streaks) while
     * everybody else WAITs; value = sum over the horizon of (own gain - rivalWeight * best rival gain) - spendCost.
     * Rival pending mirrors (hidden type) are treated as Empty. Knobs: -Dgw.p.h, -Dgw.p.rw, -Dgw.p.spend.
     */
    static final class PlannerBot implements Bot {
        private final BotState s;
        final int horizon;
        final double rivalWeight, spendCost;
        /** Rollouts per turn after WAIT's (lead 2026-11-11: a work cap, not a clock, so play does not depend on load). */
        final int rolloutCap;
        static final int DEFAULT_CAP = 250; // worst seen 169 candidates (60 seeds, 4p L4); ~6 ms at 169
        /** Largest candidate count seen in this JVM (to set the cap above the worst case). */
        static int maxCandidates;
        /** compute-scaling knobs: rivals / me play 1-ply greedy for the first oppTurns / selfTurns rollout turns; allCells = candidates on every legal cell. */
        final int oppTurns, selfTurns;
        final boolean allCells;

        /** spec: "planner" or "planner:h=20:rw=1:spend=0.3" (overrides the -Dgw.p.* defaults). */
        public PlannerBot(Config cfg, String spec) {
            s = new BotState(cfg);
            int h = Integer.getInteger("gw.p.h", 8);
            double rw = Double.parseDouble(System.getProperty("gw.p.rw", "0.25"));
            double sp = Double.parseDouble(System.getProperty("gw.p.spend", "0.5"));
            int ot = 0, st = 0;
            boolean ac = false;
            int cap = Integer.getInteger("gw.p.cap", DEFAULT_CAP);
            for (String part : spec.split(":")) {
                if (part.startsWith("opp=")) ot = Integer.parseInt(part.substring(4));
                if (part.startsWith("self=")) st = Integer.parseInt(part.substring(5));
                if (part.equals("all")) ac = true;
                if (part.startsWith("cap=")) cap = Integer.parseInt(part.substring(4));
                if (part.startsWith("h=")) h = Integer.parseInt(part.substring(2));
                else if (part.startsWith("rw=")) rw = Double.parseDouble(part.substring(3));
                else if (part.startsWith("spend=")) sp = Double.parseDouble(part.substring(6));
            }
            horizon = h;
            rivalWeight = rw;
            spendCost = sp;
            oppTurns = ot;
            selfTurns = st;
            allCells = ac;
            rolloutCap = cap;
        }

        @Override
        public void init(List<String> l) {
            s.parseInit(l);
        }

        @Override
        public String act(List<String> turnLines) {
            s.parseTurn(turnLines);
            Game base = s.game.copyWith(s.cfg);
            for (int p = 0; p < base.board.n * base.board.n; p++)
                if (s.unknownType[p]) base.board.removeMirror(p);
            int me = s.myId, n = base.board.n;
            int[] states = base.seatStates();
            Set<Integer> cells = new LinkedHashSet<>();
            for (int id = 0; id < s.playerCount; id++)
                if (base.active[id]) cells.addAll(BeamTracer.trace(base.board, base.seatOf[id], states).cells);
            if (allCells) for (int p = 0; p < n * n; p++) cells.add(p);
            List<Command> cands = new ArrayList<>();
            for (int p : cells) {
                int x = Geometry.x(p, n), y = Geometry.y(p, n);
                for (int t = 0; t < 2; t++) {
                    Command c = Command.place(x, y, t);
                    if (s.game.validate(me, c) == null) cands.add(c);
                }
                Command c = Command.turn(x, y);
                if (base.board.mirrorType[p] >= 0 && s.game.validate(me, c) == null) cands.add(c);
            }
            Command best = Command.waitCommand();
            double bestV = rollout(base, best);
            maxCandidates = Math.max(maxCandidates, cands.size());
            for (int k = 0; k < cands.size() && k < rolloutCap; k++) {
                Command c = cands.get(k);
                double v = rollout(base, c);
                if (v > bestV + 1e-9) {
                    bestV = v;
                    best = c;
                }
            }
            if (best.kind == Command.Kind.PLACE) s.myPlaced.add(Geometry.idx(best.x, best.y, n));
            return best.text();
        }


        private double rollout(Game base, Command first) {
            Game g = base.copy();
            int me = s.myId, pc = g.playerCount;
            double v = first.kind == Command.Kind.PLACE ? -spendCost : 0;
            Command[] cmds = new Command[pc];
            for (int k = 0; k < horizon && !g.isOver(); k++) {
                for (int id = 0; id < pc; id++) {
                    if (id == me) cmds[id] = k == 0 ? first : k <= selfTurns ? greedy(g, id) : Command.waitCommand();
                    else cmds[id] = k < oppTurns && g.active[id] ? greedy(g, id) : Command.waitCommand();
                }
                TurnReport r = g.playTurn(cmds);
                int rival = 0;
                for (int id = 0; id < pc; id++) if (id != me && g.active[id]) rival = Math.max(rival, r.gain[id]);
                v += r.gain[me] - rivalWeight * rival;
            }
            return v;
        }

        /** 1-ply greedy (G style) for player id on g: own gain - 0.5 best other gain, others WAIT, candidates on its own beam path. */
        private Command greedy(Game g, int id) {
            int n = g.board.n, pc = g.playerCount;
            Beam path = BeamTracer.trace(g.board, g.seatOf[id], g.seatStates());
            Command best = Command.waitCommand();
            double bestV = value(g, id, best);
            for (int p : path.cells) {
                int x = Geometry.x(p, n), y = Geometry.y(p, n);
                for (int t = 0; t < 3; t++) {
                    Command c = t < 2 ? Command.place(x, y, t) : Command.turn(x, y);
                    if (g.validate(id, c) != null) continue;
                    double v = value(g, id, c);
                    if (v > bestV + 1e-9) {
                        bestV = v;
                        best = c;
                    }
                }
            }
            return best;
        }

        private double value(Game g, int id, Command c) {
            Game t = g.copy();
            Command[] cmds = new Command[t.playerCount];
            for (int i = 0; i < cmds.length; i++) cmds[i] = i == id ? c : Command.waitCommand();
            TurnReport r = t.playTurn(cmds);
            int rival = 0;
            for (int i = 0; i < cmds.length; i++) if (i != id && t.active[i]) rival = Math.max(rival, r.gain[i]);
            return r.gain[id] - 0.5 * rival;
        }
    }

    /**
     * Level 1 boss "Wanderer" (DESIGN V5.3c): on turns t % PERIOD == 0, while it has mirrors and has placed fewer than CAP,
     * it walks its own beam from the lamp and plays the first legal (cell, type 0 then 1) whose re-traced beam lights a
     * crystal nobody lit alone last turn (litBy = -1); otherwise WAIT. No randomness, no look at rivals' beams.
     */
    static final class WandererBot implements Bot {
        public static final int PERIOD = 20, CAP = 12;
        private final BotState s;
        private final int period, cap;
        private int placed;

        public WandererBot(Config cfg) {
            this(cfg, PERIOD, CAP);
        }

        /** Other period and cap: for the tuning tables and the cap test (CAP is out of reach in 100 turns at PERIOD 20). */
        public WandererBot(Config cfg, int period, int cap) {
            s = new BotState(cfg);
            this.period = period;
            this.cap = cap;
        }

        @Override
        public void init(List<String> initLines) {
            s.parseInit(initLines);
        }

        @Override
        public String act(List<String> turnLines) {
            s.parseTurn(turnLines);
            Game g = s.game;
            if (s.turns % period != 0 || placed >= cap || g.mirrorsLeft[0] <= 0) return "WAIT";
            int n = g.board.n, seat = g.seatOf[0];
            for (int p : BeamTracer.trace(g.board, seat, g.seatStates()).cells)
                for (int type = 0; type < 2; type++) {
                    Command c = Command.place(Geometry.x(p, n), Geometry.y(p, n), type);
                    if (g.validate(0, c) == null && lightsAFreeCrystal(g, p, type)) {
                        placed++;
                        return "PLACE " + c.x + " " + c.y + " " + type;
                    }
                }
            return "WAIT";
        }

        private static boolean lightsAFreeCrystal(Game g, int p, int type) {
            Board b = g.board.copy();
            b.mirrorType[p] = type;
            b.pending[p] = 0;
            for (int c : BeamTracer.trace(b, g.seatOf[0], g.seatStates()).lit) if (g.litBy[c] == -1) return true;
            return false;
        }
    }
}

