    /** Beam directions; screen coordinates (y grows downwards). */
    static enum Dir {
        E(1, 0), S(0, 1), W(-1, 0), N(0, -1);

        public final int dx, dy;

        Dir(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /** 90 degrees clockwise on screen: (dx, dy) -> (-dy, dx). */
        public Dir rotate() {
            return values()[(ordinal() + 1) % 4];
        }

        public Dir opposite() {
            return values()[(ordinal() + 2) % 4];
        }
    }

    /** Mirror reflections: type 0 = '/', type 1 = '\'. */
    static final class Optics {
        private Optics() {}

        public static Dir reflect(int type, Dir d) {
            if (type == 0) return new Dir[] {Dir.N, Dir.W, Dir.S, Dir.E}[d.ordinal()];
            if (type == 1) return new Dir[] {Dir.S, Dir.E, Dir.N, Dir.W}[d.ordinal()];
            throw new IllegalArgumentException("mirror type " + type);
        }
    }

    /** Cell indices (idx = y * n + x) and the 90-degree board rotation R(x, y) = (n-1-y, x). */
    static final class Geometry {
        private Geometry() {}

        public static int idx(int x, int y, int n) {
            return y * n + x;
        }

        public static int x(int idx, int n) {
            return idx % n;
        }

        public static int y(int idx, int n) {
            return idx / n;
        }

        public static boolean inside(int x, int y, int n) {
            return x >= 0 && y >= 0 && x < n && y < n;
        }

        public static int rot(int idx, int n) {
            return idx(n - 1 - y(idx, n), x(idx, n), n);
        }
    }

    /** Seat geometry: seat s has its lamp at R^s(0, e) firing R^s(E); zone = Chebyshev 2 around the lamp. */
    static final class Seats {
        public static final int ZONE_RADIUS = 2;

        private Seats() {}

        /** Seat of each player id, by player count (2p: seats 0 and 2). */
        public static int[] seatsFor(int playerCount) {
            switch (playerCount) {
                case 2: return new int[] {0, 2};
                case 3: return new int[] {0, 1, 2};
                case 4: return new int[] {0, 1, 2, 3};
                default: throw new IllegalArgumentException("player count " + playerCount);
            }
        }

        public static int lampCell(int seat, int n, int e) {
            int p = Geometry.idx(0, e, n);
            for (int r = 0; r < seat; r++) p = Geometry.rot(p, n);
            return p;
        }

        public static Dir lampDir(int seat) {
            return Dir.values()[seat];
        }

        public static boolean onLampLine(int seat, int x, int y, int n, int e) {
            int lamp = lampCell(seat, n, e);
            return seat % 2 == 0 ? y == Geometry.y(lamp, n) : x == Geometry.x(lamp, n);
        }

        public static boolean inZone(int seat, int x, int y, int n, int e) {
            int lamp = lampCell(seat, n, e);
            return Geometry.inside(x, y, n)
                && Math.max(Math.abs(x - Geometry.x(lamp, n)), Math.abs(y - Geometry.y(lamp, n))) <= ZONE_RADIUS;
        }

        /** Seat whose zone holds (x, y), or -1. Zones never overlap (e >= 2, lamps on different edges). */
        public static int zoneSeat(int x, int y, int n, int e) {
            for (int s = 0; s < 4; s++) if (inZone(s, x, y, n, e)) return s;
            return -1;
        }
    }

    /** Board state: static cells (empty, wall, crystal, lamp of a seat) plus mirrors with lock and last toucher. */
    static final class Board {
        public static final int EMPTY = 0, WALL = 1, CRYSTAL = 2, LAMP = 3;
        public static final int SEAT_ACTIVE = 0, SEAT_INACTIVE = 1, SEAT_EMPTY = 2;

        public final int n, e;
        /** pending[p] > 0: the mirror is built but does not reflect yet. */
        public final int[] kind, value, lampSeat, mirrorType, mirrorLock, lastToucher, pending;
        /** mirrorLife: active turns left, -1 = no wear. phase: crystal tide phase 0..44. */
        public final int[] mirrorLife, phase;

        private Board(int n, int e) {
            this.n = n;
            this.e = e;
            int size = n * n;
            kind = new int[size];
            value = new int[size];
            lampSeat = filled(size, -1);
            mirrorType = filled(size, -1);
            mirrorLock = new int[size];
            lastToucher = filled(size, -1);
            pending = new int[size];
            mirrorLife = filled(size, -1);
            phase = new int[size];
        }

        private static int[] filled(int size, int v) {
            int[] a = new int[size];
            Arrays.fill(a, v);
            return a;
        }

        /** Empty board with the 4 seat lamps on their cells. */
        public static Board empty(int n, int e) {
            Board b = new Board(n, e);
            for (int s = 0; s < 4; s++) {
                int p = Seats.lampCell(s, n, e);
                b.kind[p] = LAMP;
                b.lampSeat[p] = s;
            }
            return b;
        }

        public Board copy() {
            Board b = new Board(n, e);
            System.arraycopy(kind, 0, b.kind, 0, kind.length);
            System.arraycopy(value, 0, b.value, 0, value.length);
            System.arraycopy(lampSeat, 0, b.lampSeat, 0, lampSeat.length);
            System.arraycopy(mirrorType, 0, b.mirrorType, 0, mirrorType.length);
            System.arraycopy(mirrorLock, 0, b.mirrorLock, 0, mirrorLock.length);
            System.arraycopy(lastToucher, 0, b.lastToucher, 0, lastToucher.length);
            System.arraycopy(pending, 0, b.pending, 0, pending.length);
            System.arraycopy(mirrorLife, 0, b.mirrorLife, 0, mirrorLife.length);
            System.arraycopy(phase, 0, b.phase, 0, phase.length);
            return b;
        }

        public void setWall(int x, int y) {
            kind[Geometry.idx(x, y, n)] = WALL;
        }

        public void setCrystal(int x, int y, int v) {
            int p = Geometry.idx(x, y, n);
            kind[p] = CRYSTAL;
            value[p] = v;
        }

        public void setMirror(int x, int y, int type) {
            mirrorType[Geometry.idx(x, y, n)] = type;
        }

        public void removeMirror(int p) {
            mirrorType[p] = -1;
            mirrorLock[p] = 0;
            pending[p] = 0;
            mirrorLife[p] = -1;
            lastToucher[p] = -1;
        }

        /** Debug text: one row per line, mirrors as / and \. */
        public String describe() {
            StringBuilder sb = new StringBuilder().append(n).append(' ').append(e).append('\n');
            for (int y = 0; y < n; y++) {
                for (int x = 0; x < n; x++) {
                    int p = Geometry.idx(x, y, n);
                    if (mirrorType[p] >= 0) sb.append(mirrorType[p] == 0 ? '/' : '\\');
                    else if (kind[p] == WALL) sb.append('#');
                    else if (kind[p] == CRYSTAL) sb.append((char) ('0' + value[p]));
                    else if (kind[p] == LAMP) sb.append((char) ('a' + lampSeat[p]));
                    else sb.append('.');
                }
                sb.append('\n');
            }
            return sb.toString();
        }
    }

    /** Result of one lamp's trace. */
    static final class Beam {
        public enum Stop { EXIT, ABSORBED, STRIKE }

        public final int seat;
        /** Crystal cells lit, in first-hit order, each once. */
        public final List<Integer> lit = new ArrayList<>();
        /** Lamp cell, then every mirror cell that turned the beam (for the viewer segments). */
        public final List<Integer> corners = new ArrayList<>();
        /** Every board cell the beam crossed, in order (lamp and stop cell excluded). */
        public final List<Integer> cells = new ArrayList<>();
        public Stop stop;
        public int struckSeat = -1;
        /** Last position: the absorbing or struck cell, or the first cell outside the board. */
        public int endX, endY;
        /** Direction of travel when the beam stopped. */
        public Dir endDir;
        public int steps;

        Beam(int seat) {
            this.seat = seat;
        }
    }

    /** Beam trace, DESIGN.md section 6.1. */
    static final class BeamTracer {
        private BeamTracer() {}

        /** @param seatState per seat: Board.SEAT_ACTIVE, SEAT_INACTIVE (lamp acts as a wall) or SEAT_EMPTY (no lamp). */
        public static Beam trace(Board b, int seat, int[] seatState) {
            return trace(b, seat, seatState, 4 * b.n * b.n);
        }

        /** @param cap step guard; reversible optics from an edge cannot loop, so the default cap is never reached. */
        static Beam trace(Board b, int seat, int[] seatState, int cap) {
            int n = b.n;
            int start = Seats.lampCell(seat, n, b.e);
            Dir d = Seats.lampDir(seat);
            int x = Geometry.x(start, n), y = Geometry.y(start, n);
            Beam beam = new Beam(seat);
            beam.corners.add(start);
            boolean[] seen = new boolean[n * n];
            while (true) {
                x += d.dx;
                y += d.dy;
                beam.steps++;
                if (!Geometry.inside(x, y, n)) {
                    beam.stop = Beam.Stop.EXIT;
                    break;
                }
                if (beam.steps > cap) throw new IllegalStateException("beam cap reached, seat " + seat);
                int p = Geometry.idx(x, y, n);
                if (b.kind[p] == Board.WALL) {
                    beam.stop = Beam.Stop.ABSORBED;
                    break;
                }
                if (b.kind[p] == Board.LAMP && seatState[b.lampSeat[p]] != Board.SEAT_EMPTY) {
                    int other = b.lampSeat[p];
                    boolean strike = other != seat && seatState[other] == Board.SEAT_ACTIVE;
                    beam.stop = strike ? Beam.Stop.STRIKE : Beam.Stop.ABSORBED;
                    if (strike) beam.struckSeat = other;
                    break;
                }
                beam.cells.add(p);
                if (b.kind[p] == Board.CRYSTAL && !seen[p]) {
                    seen[p] = true;
                    beam.lit.add(p);
                }
                if (b.mirrorType[p] >= 0 && b.pending[p] == 0) {
                    d = Optics.reflect(b.mirrorType[p], d);
                    beam.corners.add(p);
                }
            }
            beam.endX = x;
            beam.endY = y;
            beam.endDir = d;
            return beam;
        }
    }

    /** One parsed player line. Range checks belong to validation, not parsing. */
    static final class Command {
        public enum Kind { PLACE, TURN, WAIT }

        public final Kind kind;
        public final int x, y, type;
        public final String message;

        public Command(Kind kind, int x, int y, int type, String message) {
            this.kind = kind;
            this.x = x;
            this.y = y;
            this.type = type;
            this.message = message;
        }

        public static Command place(int x, int y, int type) {
            return new Command(Kind.PLACE, x, y, type, "");
        }

        public static Command turn(int x, int y) {
            return new Command(Kind.TURN, x, y, -1, "");
        }

        public static Command waitCommand() {
            return new Command(Kind.WAIT, -1, -1, -1, "");
        }

        /** Protocol text, without the message. */
        public String text() {
            return kind == Kind.PLACE ? "PLACE " + x + " " + y + " " + type : kind == Kind.TURN ? "TURN " + x + " " + y : "WAIT";
        }
    }

    /** Output parsing, DESIGN.md section 5.3: upper-case keyword, integer tokens, then an optional message. */
    static final class CommandParser {
        public static final int MESSAGE_MAX = 30;

        public static final class InvalidCommand extends Exception {
            private static final long serialVersionUID = 1L;

            InvalidCommand(String reason) {
                super(reason);
            }
        }

        private CommandParser() {}

        public static Command parse(String line) throws InvalidCommand {
            if (line == null) throw new InvalidCommand("no output");
            String[] t = line.trim().split(" +");
            switch (t[0]) {
                case "PLACE":
                    need(t, 4, line);
                    return new Command(Command.Kind.PLACE, num(t[1]), num(t[2]), num(t[3]), message(t, 4));
                case "TURN":
                    need(t, 3, line);
                    return new Command(Command.Kind.TURN, num(t[1]), num(t[2]), -1, message(t, 3));
                case "WAIT":
                    return new Command(Command.Kind.WAIT, -1, -1, -1, message(t, 1));
                default:
                    throw new InvalidCommand("unknown command: " + cut(line));
            }
        }

        private static void need(String[] t, int count, String line) throws InvalidCommand {
            if (t.length < count) throw new InvalidCommand("missing arguments: " + cut(line));
        }

        private static int num(String s) throws InvalidCommand {
            try {
                return Integer.parseInt(s);
            } catch (NumberFormatException ex) {
                throw new InvalidCommand("not an integer: " + cut(s));
            }
        }

        private static String message(String[] t, int from) {
            StringBuilder sb = new StringBuilder();
            for (int i = from; i < t.length; i++) sb.append(i > from ? " " : "").append(t[i]);
            return cut(sb.toString());
        }

        private static String cut(String s) {
            return s.length() <= MESSAGE_MAX ? s : s.substring(0, MESSAGE_MAX);
        }
    }

    /** Rule switches and constants (DESIGN F1); every (T) tunable value lives here only. */
    static final class Config {
        public int maxTurns = 150;
        /** DESIGN V5.5 early end: "decided" (no pair can change order) and "stale" (all idle STALE_TURNS turns). */
        public boolean earlyEnd = true;
        public int staleTurns = 20;
        /** Mirrors in hand at the start (Wood: the whole stock). */
        public int mirrorStock = 4;
        /** +1 mirror before the input of turns t % supplyEvery == 0 (0 = no supply), hand capped at handMax. */
        public int supplyEvery = 4;
        public int handMax = 6;
        public int lock = 5;
        public boolean turnAllowed = true;
        /** Placed mirrors are pending 1 turn (reflect from t+2) and their type is hidden from rivals. */
        public boolean buildDelay = true;
        public boolean sealed = true;
        /** Active turns before a mirror breaks; -1 = never. */
        public int mirrorLife = 20;
        /** Crystals sleep: awake when (turn + phase) % tideCycle < tideAwake. */
        public boolean tides = false;
        public int tideCycle = 45;
        public int tideAwake = 30;
        /** false: every beam on a crystal scores it (Wood 2). */
        public boolean contested = true;
        public int streakCap = 4;
        public int strikeBonus = 0;
        /** Map options: rocks and start mirrors; crystal values 1-3 (else all 1). */
        public boolean walls = true;
        public boolean multiValues = false;

        public Config copy() {
            Config c = new Config();
            c.maxTurns = maxTurns;
            c.earlyEnd = earlyEnd;
            c.staleTurns = staleTurns;
            c.mirrorStock = mirrorStock;
            c.supplyEvery = supplyEvery;
            c.handMax = handMax;
            c.lock = lock;
            c.turnAllowed = turnAllowed;
            c.buildDelay = buildDelay;
            c.sealed = sealed;
            c.mirrorLife = mirrorLife;
            c.tides = tides;
            c.tideCycle = tideCycle;
            c.tideAwake = tideAwake;
            c.contested = contested;
            c.streakCap = streakCap;
            c.strikeBonus = strikeBonus;
            c.walls = walls;
            c.multiValues = multiValues;
            return c;
        }

        public static Config bronze() {
            return new Config();
        }

        public static Config silver() {
            Config c = bronze();
            c.tides = true;
            c.multiValues = true;
            c.strikeBonus = 2;
            return c;
        }

        public static Config woodOne() {
